import{z as o,x as s,o as e,c as p,q as r,j as n,D as E,d as A,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const q=JSON.parse('{"title":"组合案例与收束","description":"","frontmatter":{"title":"组合案例与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-case-map.md","filePath":"quant/pf-case-map.md","lastUpdated":1791063341000}'),d={name:"quant/pf-case-map.md"};function f(u,a,m,h,D,c){const B=s("Mermaid");return e(),p("div",null,[a[2]||(a[2]=r('<h1 id="组合案例与收束" tabindex="-1">组合案例与收束 <a class="header-anchor" href="#组合案例与收束" aria-label="Permalink to &quot;组合案例与收束&quot;">​</a></h1><div class="epigraph"><p>组合构建的全部知识，只在「从因子清单到月末账单」的路上同时为真；收束课把这条路走两遍，再给你一张地图。</p><footer>—— 据 Markowitz, Journal of Finance, 1952；Michaud, Financial Analysts Journal, 1989；Grinold and Kahn, Active Portfolio Management, 2000 的口径整理</footer></div><p><a href="/quant/pf-ml-in-portfolio">上一课</a>把机器学习接进构建管线：分层接入、不确定性进优化、成本链验收。本课是组合构建深化的收束课：两个案例把十一课的机器串起来跑一遍，然后给出课程的地图。单课视角的盲区在接缝：每环单独都对、连起来错——收束检查的正是接口。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>接口失败的三种典型。数值层与统计层的接缝：扰动验收过关的解，喂进的是一份过时的 \\(\\Sigma\\)——稳定地错。政策层与目标层的接缝：税优的再平衡（卖出亏损、保留盈利）悄悄改变了因子暴露，归因报告里以「风格漂移」现形——政策在它自己的会计里正确，在账本里欠账。防御层与资负层的接缝：对冲预算在压力情景里被证明买错了凸性——情景库没有覆盖对冲工具自身的基差。两个案例各暴露一类接缝。</p><p><span class="marginnote">「接缝」是两个环节交界处对口径的隐含假设：上游输出的格式、时点、单位，下游默认照单全收。直觉类比：两个软件模块各自单元测试都通过，连起来却崩——崩的从来不是模块本身，而是中间没人签收的接口；组合构建的「估计到政策」「政策到账本」同理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把两个案例当接口测试来跑：每个案例沿同一条流水线走全程——估计、正则化、政策、防御、账本——只换外部条件，不换验收口径。案例的产出不是复盘叙事，而是一张标了地址的接口修正清单：凡是需要人工「翻译」才能通过的接缝，就是失败点，事后由压力测试与归因对账把地址钉实。</p><h3 id="案例一-多资产风险平价遇上-2022" tabindex="-1">案例一：多资产风险平价遇上 2022 <a class="header-anchor" href="#案例一-多资产风险平价遇上-2022" aria-label="Permalink to &quot;案例一：多资产风险平价遇上 2022&quot;">​</a></h3><p>通胀冲击让股债相关转正：体制分层的协方差估计（<a href="/quant/pf-multiasset">多资产组合</a>）若只做了形式分层，此时给出的对冲比照旧；波动目标自动减仓（<a href="/quant/vol-targeting">波动目标</a>）与再平衡带宽（<a href="/quant/pf-rebalancing">再平衡策略学</a>）争夺同一笔交易——带宽过松，减仓落在风险兑现之后；杠杆的保证金追缴（<a href="/quant/futures-margin">期货保证金</a>）与展期成本挤占现金流；尾部预算若只买了股指 put，对冲的是股票左尾，不覆盖债券的实际波动。事后复盘的压力测试（<a href="/quant/pf-stress-testing">组合压力测试</a>）把「通胀驱动的双杀」从假设情景升级为必测情景——产出是接口修正，不是失误名单。</p><p><span class="marginnote">「再平衡带宽」是允许权重偏离目标的缓冲区，如目标 30% 的资产设 ±3%：偏离不出带宽就不交易。为什么重要：带宽设得太宽，波动目标触发的减仓会因「还没出带宽」被跳过，等风险真的兑现了才动手——2022 年里这正是两个模块争抢同一笔交易的形状。</span></p><h3 id="案例二-应税账户接入一条动量因子" tabindex="-1">案例二：应税账户接入一条动量因子 <a class="header-anchor" href="#案例二-应税账户接入一条动量因子" aria-label="Permalink to &quot;案例二：应税账户接入一条动量因子&quot;">​</a></h3><p>因子账本交付约定显式的动量信号（因子研究深化的出口）；第一道关是<a href="/quant/pf-optimizer-numerics">优化器的数值稳定性</a>：扰动测试显示高换手动量的权重稳定带极窄，<a href="/quant/pf-regularized">正则化组合</a>的 \\(\\ell_1\\) 与换手惩罚把换手压到成本线上；<a href="/quant/pf-tax-aware">税负敏感的组合</a>用批次识别与损失收获吸收实现税，替代持仓维持暴露；<a href="/quant/pf-ml-in-portfolio">组合中的机器学习</a>的 meta-labeling 只调仓位不改方向；季度末由<a href="/quant/pf-attribution-deep">绩效归因的深化</a>对账：税负单列、残差在预算内、动量的钱可指认。两个案例共用一条流水线。</p><p><span class="marginnote">「损失收获」就是在应税账户里主动卖出浮亏的持仓，把亏损实现成可抵税的项目，同时换入相似资产保持敞口。数字实例：实现 10 万元亏损、按 20% 的资本利得税率，约可少缴 2 万元的税——这是动量这类高换手策略在应税账户里还能存活的隐形补贴。</span></p>',14)),(e(),n(l,null,{default:E(()=>[i(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%EF%BC%9A%E5%9B%A0%E5%AD%90%E4%B8%8E%E8%A7%82%E7%82%B9%EF%BC%88%E4%B8%8A%E4%B8%80%E9%97%A8%E8%AF%BE%E7%9A%84%E5%87%BA%E5%8F%A3%EF%BC%89%22%5D%20--%3E%20EST%5B%22%E4%BC%B0%E8%AE%A1%EF%BC%9A%E6%95%B0%E5%80%BC%E9%AA%8C%E6%94%B6%E4%B8%8E%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%22%5D%0A%20%20EST%20--%3E%20REG%5B%22%E6%AD%A3%E5%88%99%E5%8C%96%EF%BC%9A%E4%B8%8D%E4%BF%A1%E4%BB%BB%E7%9A%84%E5%A3%B0%E6%98%8E%22%5D%0A%20%20REG%20--%3E%20POL%5B%22%E6%94%BF%E7%AD%96%EF%BC%9A%E5%86%8D%E5%B9%B3%E8%A1%A1%E3%80%81%E7%A8%8E%E3%80%81%E5%A4%9A%E8%B5%84%E4%BA%A7%E5%B7%A5%E5%85%B7%22%5D%0A%20%20POL%20--%3E%20DEF%5B%22%E9%98%B2%E5%BE%A1%EF%BC%9A%E5%B0%BE%E9%83%A8%E9%A2%84%E7%AE%97%E4%B8%8E%E5%8E%8B%E5%8A%9B%E6%83%85%E6%99%AF%22%5D%0A%20%20DEF%20--%3E%20LED%5B%22%E8%B4%A6%E6%9C%AC%EF%BC%9A%E5%BD%92%E5%9B%A0%E9%97%AD%E5%90%88%E4%B8%8E%E6%AE%8B%E5%B7%AE%E9%A2%84%E7%AE%97%22%5D%0A%20%20LED%20--%3E%20ML%5B%22%E5%AD%A6%E4%B9%A0%EF%BC%9AML%20%E6%8E%A5%E5%85%A5%E4%B8%8E%E6%88%90%E6%9C%AC%E9%93%BE%E8%AF%84%E4%BB%B7%22%5D%0A%20%20ML%20--%3E%7C%E5%8F%8D%E9%A6%88%E5%9B%9E%E4%BC%B0%E8%AE%A1%7C%20EST%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"为什么案例要跨体制：案例的价值在暴露隐藏假设——2022 暴露的是「平滑相关与低利率 carry」假设，应税案例暴露的是「税前效用」假设；每条假设在被击穿前都不可见，把两条已知裂纹摆在一起，接口清单就从演练变成经验。为什么流水线要闭环：归因与压力的发现流回估计与政策，与因子研究收束课的闭环同构——没有回边的部门反复在同一接口上犯同一类错，有回边的部门，每次危机都在提高下一版构建的存活率。三句话带走这门课：优化器是误差放大器，纪律从数值层开始；约束、税与再平衡不是实现细节，是策略本身；验收在成本链与危机故事上，不在样本内夏普上。",-1)),(e(),n(l,null,{default:E(()=>[i(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E9%80%9A%E8%83%80%E5%86%B2%E5%87%BB%22%5D%20--%3E%20C%5B%22%E8%82%A1%E5%80%BA%E7%9B%B8%E5%85%B3%E6%80%A7%E8%BD%AC%E6%AD%A3%22%5D%0A%20%20C%20--%3E%20A%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%E5%88%86%E5%B1%82%E5%A4%B1%E6%95%88%EF%BC%9A%E5%AF%B9%E5%86%B2%E6%AF%94%E7%85%A7%E6%97%A7%22%5D%0A%20%20I%20--%3E%20V%5B%22%E6%B3%A2%E5%8A%A8%E8%B7%B3%E5%8D%87%E8%A7%A6%E5%8F%91%E6%B3%A2%E5%8A%A8%E7%9B%AE%E6%A0%87%E5%87%8F%E4%BB%93%22%5D%0A%20%20V%20--%3E%20B%5B%22%E4%B8%8E%E5%86%8D%E5%B9%B3%E8%A1%A1%E5%B8%A6%E5%AE%BD%E4%BA%89%E5%A4%BA%E5%90%8C%E4%B8%80%E7%AC%94%E4%BA%A4%E6%98%93%22%5D%0A%20%20I%20--%3E%20M%5B%22%E5%80%BA%E5%88%B8%E5%AE%9E%E9%99%85%E6%B3%A2%E5%8A%A8%EF%BC%8C%E8%82%A1%E6%8C%87%20put%20%E4%B8%8D%E8%A6%86%E7%9B%96%22%5D%0A%20%20A%20--%3E%20X%5B%22%E5%A4%9A%E8%B5%84%E4%BA%A7%E7%BB%84%E5%90%88%E5%90%8C%E6%97%B6%E5%8F%97%E4%BC%A4%22%5D%0A%20%20B%20--%3E%20X%0A%20%20M%20--%3E%20X%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">接口自查的一句话版本：任何一个环节的输出，能否以其下游要求的格式与口径被无修改地消费？因子清单到估计、估计到政策、政策到账本——每处「翻译」都是下一次事故的候选地址。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不进入波动率产品的定价与对冲细节（波动率交易深化课程的对象），不展开机构风险治理与限额体系（风险体系深化课程的对象），不替代执行层的算法选择（交易执行课程）。方法论不替你选择目标函数与政策参数——它收敛于让每个选择可审计：数值有稳定带，正则有对偶口径，政策有成本核，防御有情景库，账本有残差预算。深钻的尽头是接口的纪律：下一门课的波动率，会以同样的方式验收本课程交出的组合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两个案例各暴露一类接缝：前者在防御与资负之间，后者在政策与账本之间。</li><li>流水线闭环：归因与压力的发现流回估计与政策，每次危机提高下一版的存活率。</li><li>三句话：优化器是误差放大器；约束与政策即策略；验收在成本链与危机故事上。</li><li>课程地图：输入、估计、正则化、政策、防御、账本、学习，七站各有验收标准。</li><li>出处：Markowitz, <em>JF</em>, 1952；Michaud, <em>FAJ</em>, 1989；Grinold &amp; Kahn, <em>Active Portfolio Management</em>, 2000。</li></ul>',5))])}const F=o(d,[["render",f]]);export{q as __pageData,F as default};
